window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5acba33758ce7e9e"]={"versions": [{"id": "FIG-5acba33758ce7e9e", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses im AUTOSAR-E2E-Protokoll (End-to-End Communication Protection), spezifisch für das Profil 11 (E2E Profile 11). Das Diagramm modelliert den Teilschritt „Write CRC“ innerhalb der Routinen <code>E2E_P11Protect()</code> und <code>E2E_P11Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext-Konnektoren / Aufrufrahmen:</strong></li>\n<li><code>E2E_P11Protect()</code> (mit Subaktivitäts-Symbol)</li>\n<li><code>E2E_P11Forward()</code> (mit Subaktivitäts-Symbol)</li>\n<li><strong>Aktion:</strong></li>\n<li><code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;CRCOffset/8]</code></li>\n<li><strong>Knoten des Steuerungsflusses:</strong></li>\n<li>Startknoten (Initial Node, ausgefüllter schwarzer Kreis)</li>\n<li>Endknoten (Activity Final Node, konzentrischer Kreis mit Kern)</li>\n<li><strong>Datenobjekte und Parameter:</strong></li>\n<li>Lokale Variable: <code>ComputedCRC</code> (1 Byte groß, <code>uint8</code>)</li>\n<li>Konfigurationsstruktur: <code>Config-&gt;CRCOffset</code> (Offset-Angabe in Bits)</li>\n<li>Zielpuffer / Nutzdaten-Array: <code>Data[]</code> (Byte-Array)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Startknoten verzweigt der Kontrollfluss sequenziell in die Aktionsstufe <code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;CRCOffset/8]</code>.</li>\n<li>Innerhalb der Aktion wird der vorberechnete 1-Byte-Wert <code>ComputedCRC</code> an die über <code>Config-&gt;CRCOffset / 8</code> adressierte Byte-Position im Datenarray <code>Data</code> geschrieben.</li>\n<li>Nach Abschluss des Kopiervorgangs geht der Kontrollfluss direkt in den Aktivitätsendknoten über.</li>\n<li>Der Teilschritt wird identisch von beiden übergeordneten Funktionen <code>E2E_P11Protect()</code> und <code>E2E_P11Forward()</code> ausgeführt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung dieses Schritts ist normativ gemäß <code>[PRS_E2E_00514]</code>. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Die Bitposition <code>CRCOffset</code> in der Konfiguration muss durch 8 teilbar sein (Byte-Ausrichtung).</li>\n<li>Das Datenarray <code>Data</code> muss ausreichend allokiert sein, sodass der Index <code>Config-&gt;CRCOffset / 8</code> innerhalb der gültigen Grenzen (<code>Length</code>) liegt.</li>\n<li>Vor dem Schreiben der CRC muss <code>ComputedCRC</code> bereits nach den Regeln von Profil 11 (<code>[PRS_E2E_00513]</code>) berechnet worden sein.</li>\n<li>Der Schreibzugriff platziert genau 1 Byte der Prüfsumme ohne Beeinflussung benachbarter Nutzdatenbytes.</li>\n</ul>"}, {"id": "FIG-2bb61c513831f537", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses im AUTOSAR-E2E-Protokoll (End-to-End Communication Protection), spezifisch für das Profil 11 (E2E Profile 11). Das Diagramm modelliert den Teilschritt „Write CRC“ innerhalb der Routinen <code>E2E_P11Protect()</code> und <code>E2E_P11Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Kontext-Konnektoren / Aufrufrahmen:</strong></li>\n<li><code>E2E_P11Protect()</code> (mit Subaktivitäts-Symbol)</li>\n<li><code>E2E_P11Forward()</code> (mit Subaktivitäts-Symbol)</li>\n<li><strong>Aktion:</strong></li>\n<li><code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;CRCOffset/8]</code></li>\n<li><strong>Knoten des Steuerungsflusses:</strong></li>\n<li>Startknoten (Initial Node, ausgefüllter schwarzer Kreis)</li>\n<li>Endknoten (Activity Final Node, konzentrischer Kreis mit Kern)</li>\n<li><strong>Datenobjekte und Parameter:</strong></li>\n<li>Lokale Variable: <code>ComputedCRC</code> (1 Byte groß, <code>uint8</code>)</li>\n<li>Konfigurationsstruktur: <code>Config-&gt;CRCOffset</code> (Offset-Angabe in Bits)</li>\n<li>Zielpuffer / Nutzdaten-Array: <code>Data[]</code> (Byte-Array)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Startknoten verzweigt der Kontrollfluss sequenziell in die Aktionsstufe <code>Copy 1-byte local variable ComputedCRC on bytes Data[Config-&gt;CRCOffset/8]</code>.</li>\n<li>Innerhalb der Aktion wird der vorberechnete 1-Byte-Wert <code>ComputedCRC</code> an die über <code>Config-&gt;CRCOffset / 8</code> adressierte Byte-Position im Datenarray <code>Data</code> geschrieben.</li>\n<li>Nach Abschluss des Kopiervorgangs geht der Kontrollfluss direkt in den Aktivitätsendknoten über.</li>\n<li>Der Teilschritt wird identisch von beiden übergeordneten Funktionen <code>E2E_P11Protect()</code> und <code>E2E_P11Forward()</code> ausgeführt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Ausführung dieses Schritts ist normativ gemäß <code>[PRS_E2E_00514]</code>. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\">\n<li>Die Bitposition <code>CRCOffset</code> in der Konfiguration muss durch 8 teilbar sein (Byte-Ausrichtung).</li>\n<li>Das Datenarray <code>Data</code> muss ausreichend allokiert sein, sodass der Index <code>Config-&gt;CRCOffset / 8</code> innerhalb der gültigen Grenzen (<code>Length</code>) liegt.</li>\n<li>Vor dem Schreiben der CRC muss <code>ComputedCRC</code> bereits nach den Regeln von Profil 11 (<code>[PRS_E2E_00513]</code>) berechnet worden sein.</li>\n<li>Der Schreibzugriff platziert genau 1 Byte der Prüfsumme ohne Beeinflussung benachbarter Nutzdatenbytes.</li>\n</ul>"}], "trans": [{"from": "FIG-5acba33758ce7e9e", "to": "FIG-2bb61c513831f537", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
